import type { LevelContent } from './types';

/** The `conceptual` level of every section that has one, keyed by section id. */
export const CONCEPTUAL: Readonly<Record<string, LevelContent>> = {"extraction":{"title":"What Fondok reads from your documents","blocks":[{"type":"container","kind":"intro","attrs":{},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Every uploaded document moves through the same stages: it is read, filed by type, its figures are extracted and checked, and the result is reconciled against the statement's own totals. Nothing is typed in by Fondok — a figure the documents do not state stays a dash. A deal that is still a draft — its setup in the New Deal wizard not yet finished — has no model outputs: its documents are read and extracted as they are added, but nothing is projected, exported or written into a memo until Finish turns it into a live deal. The property's name is one of the things read from the Offering Memorandum; the wizard does not ask for it."}]}]},{"type":"container","kind":"stages","attrs":{},"children":[{"type":"container","kind":"stage","attrs":{"n":"1","icon":"FileText"},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Read"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"PDFs, Excel workbooks, CSV files, Word documents and PowerPoint decks are read into text and tables. A scanned PDF with no readable text layer is marked as unreadable in the Data Room with a Retry, rather than quietly producing nothing."}]}]},{"type":"container","kind":"stage","attrs":{"n":"2","icon":"Sparkles"},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Classify"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Fondok reads the file name and first pages and files the document as an Offering Memorandum, T-12, P&L, STR report, market study, benchmark report, rent roll, hotel program, capital plan, insurance, tax or contract. A document dropped without a tag is marked “Classified automatically — confirm” in the Data Room until you confirm or change the type."}]}]},{"type":"container","kind":"stage","attrs":{"n":"3","icon":"BarChart3"},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Extract"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Every grounded figure, identifier and date is pulled into a typed list, each entry carrying the page it was read from and a confidence score. Anything not grounded in the source is dropped. A field below the review threshold is flagged in the Data Room and in the Historical P&L until you accept or correct it."}]}]},{"type":"container","kind":"stage","attrs":{"n":"4","icon":"Database"},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Reconcile"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"When a T-12 or P&L carries its own summary sheet, the extracted lines are checked against it: a department total that disagrees with the statement's own summary by more than five percent is replaced with the summary value, and the original is kept beside it for review. A revenue line far below the deal's other full-period statements is held for review so a single outlet line can never pass as the department total."}]}]},{"type":"container","kind":"stage","attrs":{"n":"5","icon":"Link2"},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Verify"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"A second pass re-reads each cited figure against the page it came from. A figure that matches earns a high confidence; one that does not is lowered so it shows as “to review”. The confidence badge beside each field is this result."}]}]},{"type":"container","kind":"stage","attrs":{"n":"6","icon":"ArrowRight"},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"File the period"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The statement's own period — a full year, a year to date or a trailing twelve months — is read off the document, so a single-month upload never outranks an annual statement when the model chooses its Year-1 basis."}]}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Jobs that stall are timed out, never left spinning"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"A document that stops moving for half an hour is marked Failed with the stage it stopped in and the time elapsed, and the Data Room offers Retry. Nothing is wrong with the file — the same bytes run again from the start. A retry on a document that is still moving is refused, so two runs never work on one file at once."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Re-running extraction"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Any finished document can be extracted again from the Data Room — one at a time, or every document on the deal. A confirmation step says what will happen first. The re-run is fresh under the current version of the pipeline. Field reviews made on the previous result (accepted, edited or rejected values) are not carried over, so anything the new result flags needs reviewing again; the previous result is kept as history. The document type and year you set are kept, and a disagreement with the new read is flagged for confirmation. Your model assumptions and their justification notes live on the deal and are untouched. When the last document finishes, the model runs once."}]}]},{"type":"container","kind":"card","attrs":{"testid":"methodology-duplicate-deal"},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Duplicating a deal before re-testing"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Because a re-extraction does not carry field reviews over, “Duplicate deal” in the deal header menu makes a working copy first. The copy carries the deal details, every assumption with its justification note, the scenarios, and every document with its latest extraction — including the fields you accepted, edited or rejected. The documents point at the same stored files; nothing is uploaded again. P&L cell comments are copied only when you tick the box in the confirmation. Model runs and the activity history are not copied: the copy shows no results until the model is run on it. The original is not changed."}]}]}]},"projection":{"title":"How the Future P&L is built","blocks":[{"type":"container","kind":"intro","attrs":{},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Year 1 is anchored on the deal's own statements whenever they exist; later years grow from an undisplaced baseline, so a renovation year does not permanently depress the curve. The order of precedence for each input is below."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Year-1 occupancy and ADR"}]},{"type":"container","kind":"chain","attrs":{},"children":[{"type":"list","ordered":true,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Your override"}]},{"type":"text","value":" — Set in the inline editor on the Overview or the P&L — wins over every other source and carries your justification note."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"T-12 actual"}]},{"type":"text","value":" — Read from the statement the Data Room badges as Primary source: full-year statements first, the most recent period first, a T-12 ahead of a calendar-year P&L of the same year."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Market forecast"}]},{"type":"text","value":" — When the deal has no T-12 but a CBRE Hotel Horizons report is uploaded, its Year-1 forecast for the submarket and chain scale anchors the year."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Platform default"}]},{"type":"text","value":" — A last-resort fallback used only on deals with no extracted data, badged as a default so it is never mistaken for a sourced figure."}]}]}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"The projection calendar"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The model projects operating years — Year 1 through the end of the hold — and places them on the calendar from one date: the "},{"type":"strong","children":[{"type":"text","value":"acquisition close date"}]},{"type":"text","value":". Operating Year 1 is the calendar year of the first operating month after close, so a September close projects Year 1 in the same year and a December close projects it in the next. With no close date the statement prints no calendar year at all; a guessed year would be an invented number."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The first column is labelled "},{"type":"strong","children":[{"type":"text","value":"Base year (Year 1)"}]},{"type":"text","value":" because that is what it is: the model's first operating year, the year the returns and the Cash Flow statement call Year 1. The horizon is the hold period plus one "},{"type":"strong","children":[{"type":"text","value":"Exit Year"}]},{"type":"text","value":" column, which carries only the forward twelve-month NOI the sale is valued on."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Every projection year-end is also evaluated as a sale date — the "},{"type":"strong","children":[{"type":"text","value":"Returns by exit year"}]},{"type":"text","value":" table on the Returns summary — on this same projection: the operating years are not re-projected for a shorter hold. Years beyond the hold are not projected, so they are not shown; a longer hold is a different underwriting, not a row."}]}]},{"type":"container","kind":"card","attrs":{"testid":"methodology-line-methods"},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Expense lines and their methods"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Eight expense lines — Rooms, F&B and Other Operated departmental expense, and Administrative & General, Information & Telecom, Sales & Marketing, Property Operations and Utilities — can each be driven one of four ways from the method chip on their Future P&L row: "},{"type":"strong","children":[{"type":"text","value":"Growth"}]},{"type":"text","value":" (Year 1 grown each year), "},{"type":"strong","children":[{"type":"text","value":"% of revenue"}]},{"type":"text","value":" (the department's own revenue for departmental lines, total revenue for undistributed lines), "},{"type":"strong","children":[{"type":"text","value":"per occupied room"}]},{"type":"text","value":" and "},{"type":"strong","children":[{"type":"text","value":"per available room"}]},{"type":"text","value":". A method picked without a value keeps the line's own Year-1 ratio, so no benchmark figure is introduced. A line nobody has touched runs exactly as before. Every method change needs a justification note, and the Excel export lists each line's method and value on its Assumptions sheet."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Operating model."}]},{"type":"text","value":" The new-deal wizard records whether the hotel is owner-operated, third-party managed or brand-managed. It is shown on the Overview and beside the management fee. It moves no number: the management fee is yours to set, and the check against the usual two to six percent of revenue applies to every operating model."}]},{"type":"paragraph","attrs":{"testid":"methodology-incentive-fee"},"inline":[{"type":"strong","children":[{"type":"text","value":"Base and incentive management fee."}]},{"type":"text","value":" The management fee is the base fee — a share of each year's total revenue. The incentive fee beside it is optional and blank by default. When set, each year's incentive fee is a share of gross operating profit after the base fee, never negative, deducted before NOI, so it lowers NOI and everything downstream. It appears as its own row only when set, and travels through the Excel export."}]},{"type":"container","kind":"box","attrs":{"testid":"methodology-mgmt-fee-guidance"},"children":[{"type":"heading","level":5,"inline":[{"type":"text","value":"Management fee — directional guidance by operating model"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"em","children":[{"type":"slot","name":"mgmt-fee-disclaimer"}]},{"type":"text","value":" The same text is shown beside the management fee on the Future P&L."}]},{"type":"slot","name":"mgmt-fee-guidance"}]}]},{"type":"container","kind":"card","attrs":{"testid":"methodology-future-pl"},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Reading the Future P&L"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The P&L tab has two views: "},{"type":"strong","children":[{"type":"text","value":"Historical P&L"}]},{"type":"text","value":" — the normalised actuals, one column per fiscal year — and "},{"type":"strong","children":[{"type":"text","value":"Future P&L"}]},{"type":"text","value":", the forward plan the returns are built on. Every projected column is headed by its operating year and calendar year; the first column also names the statement period it is anchored on, exactly as the Historical P&L heads that column."}]},{"type":"paragraph","attrs":{"testid":"primary-statement-methodology"},"inline":[{"type":"strong","children":[{"type":"text","value":"One statement per year."}]},{"type":"text","value":" When two statements cover the same fiscal year (a detailed and a summary P&L, say), the Historical P&L shows one column, built from the primary statement, and names the other as supplemental on that column. The primary is the one that drives the model: the statement the Data Room marks “Primary source” — a full-year statement ahead of a partial one, then the fuller extraction, then the newer upload. Re-tag a statement's year in the Data Room to change which is primary."}]},{"type":"paragraph","attrs":{"testid":"correction-note-methodology"},"inline":[{"type":"strong","children":[{"type":"text","value":"Correcting an extracted value."}]},{"type":"text","value":" A statement figure can be corrected where it is read — from a flagged cell on the Historical P&L, from the Data Room review list, or by re-importing the exported workbook. Every correction asks why, and the note is kept with the corrected value and in the audit trail, the same as a model override: a corrected statement value is model input."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Click any number."}]},{"type":"text","value":" Every projected occupancy, ADR, RevPAR and statement amount opens a trace of the inputs behind it — starting value, growth, index or penetration where present — down to the source rows. When no trace was recorded for a cell the drawer says so; Fondok never prints a formula it did not record."}]},{"type":"paragraph","attrs":{"testid":"benchmark-column-methodology"},"inline":[{"type":"strong","children":[{"type":"text","value":"Benchmark column."}]},{"type":"text","value":" When the deal carries a P&L benchmark report (CBRE or HotStats), the Base-year column gains a Benchmark sub-column showing the comparable set's ratio for thirteen lines on the same basis as the model's own ratio, and the difference in points. Colour marks direction only, never a verdict. A line the report did not publish shows a dash with the reason. The fuller comparison sits under the collapsed Benchmark detail below the table, and the Excel export carries the ratios as a read-only column."}]},{"type":"paragraph","attrs":{"testid":"benchmark-suggestions-methodology"},"inline":[{"type":"strong","children":[{"type":"text","value":"Benchmarks are suggestions."}]},{"type":"text","value":" A benchmark never flows into the model on its own. For the Rooms and F&B departmental ratios, the management fee and the FF&E reserve, Fondok turns the report into a suggestion that names the value, the benchmark line, the peer-set size, the document and page, and the value the model is on now. "},{"type":"em","children":[{"type":"text","value":"Apply benchmark"}]},{"type":"text","value":" opens a prefilled justification note you can edit; saving writes an ordinary analyst override and re-runs the model. "},{"type":"em","children":[{"type":"text","value":"Reset to source"}]},{"type":"text","value":" removes it again. Until you act, each assumption keeps its existing source: your portfolio ratio when one is on the deal, else the platform default, labelled as such."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"The waterfall below Total Revenue"}]},{"type":"text","value":" runs gross operating profit, then management fees (and the incentive fee when one is modelled), then fixed charges — property taxes, insurance, rent, other — to "},{"type":"strong","children":[{"type":"text","value":"NOI (before FF&E reserve)"}]},{"type":"text","value":", then the FF&E reserve, to "},{"type":"strong","children":[{"type":"text","value":"Cash NOI (after FF&E reserve)"}]},{"type":"text","value":". Each line is labelled with its basis, and the two NOI figures differ by exactly the reserve. Where the product says simply “NOI” it means the before-reserve figure, the numerator of the entry cap rate. The after-reserve figure is what debt coverage and the exit valuation use."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"The Stabilization Year"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"“Stabilized” names one projection year, and every stabilized figure on every screen — occupancy, ADR, revenue, NOI, NOI margin, yield on cost, the IC memo's scenario summary and Scenario Analysis' comparison row — is read from that year, published once so two screens cannot disagree."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The stabilization year defaults to "},{"type":"strong","children":[{"type":"text","value":"Year 3 of operations"}]},{"type":"text","value":" (badged “Default — confirm”); on a shorter hold it is the last projected year, and the card says so. You can override it on the Future P&L's Assumptions panel. It is a "},{"type":"strong","children":[{"type":"text","value":"reporting"}]},{"type":"text","value":" assumption: it selects which year the stabilized figures are read from and moves no cash flow, so changing it leaves the sale price, both IRRs and the equity multiple unchanged."}]},{"type":"paragraph","attrs":{"testid":"methodology-stabilization-anchor"},"inline":[{"type":"strong","children":[{"type":"text","value":"What Year 3 counts from."}]},{"type":"text","value":" With no reopening date the default counts from the acquisition close, and the Overview reads “Year 3 after close”. For a material repositioning or re-flag, set the "},{"type":"strong","children":[{"type":"text","value":"reopening date"}]},{"type":"text","value":" on the Overview's Investment Profile card: the default then counts Year 3 from the first full operating year after reopening, and every stabilized figure says so (“Year 3 after reopening”). A reopening Fondok cannot place — no close date, or a Year 3 that falls before the projection starts — keeps the close anchor and states the exception in plain sight wherever the anchor is shown. Stabilized NOI stays a separate figure from the exit NOI the sale is valued on; the two are never printed under one label."}]}]},{"type":"container","kind":"card","attrs":{"testid":"methodology-exit-basis"},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"What the exit is valued on"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The sale capitalises the "},{"type":"strong","children":[{"type":"text","value":"forward twelve-month Cash NOI"}]},{"type":"text","value":" — the after-reserve basis — at the exit cap rate. That forward figure is the last hold year's Cash NOI grown at the RevPAR growth rate; the Exit Year column shows this and nothing else. On CAPEX → Exit you can switch the basis to "},{"type":"strong","children":[{"type":"text","value":"Stabilized NOI"}]},{"type":"text","value":" (the stabilized year's Cash NOI grown to the exit) or to "},{"type":"strong","children":[{"type":"text","value":"Sale-year NOI"}]},{"type":"text","value":" — the exit year's own Cash NOI, not grown — and an analyst-entered terminal NOI beats any basis. Wherever the exit NOI is printed its label names the basis and period it was taken on."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"In the Returns by exit year table the forward twelve-month basis follows one rule for the interim years: the exit NOI is the "},{"type":"strong","children":[{"type":"text","value":"next projected year's Cash NOI"}]},{"type":"text","value":" where the projection has it, and the final year is grown at the RevPAR growth rate because no later year is projected. A pinned (analyst-entered) terminal NOI applies to the selected exit only; every row names its own basis and period beside its exit NOI."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The entry cap rate is struck on NOI "},{"type":"em","children":[{"type":"text","value":"before"}]},{"type":"text","value":" the reserve while the exit is struck on Cash NOI "},{"type":"em","children":[{"type":"text","value":"after"}]},{"type":"text","value":" it. Both are defensible conventions; Fondok keeps both and names each one wherever it prints it, never a bare “NOI”."}]}]},{"type":"container","kind":"card","attrs":{"testid":"methodology-returns-by-exit-year"},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Returns by exit year"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The Returns summary carries one row for every projection year-end, each answering “what if the deal were sold then?” on the same projection. A row sells at that year-end on the basis above, applies the same selling costs and transfer tax, pays off the loan balance at that date, and includes the refinance only if it precedes the sale. Each row shows the exit NOI with its basis, the gross sale, the payoff, the net proceeds to equity, the unlevered and levered IRR and the equity multiple. The row with the highest levered IRR is marked "},{"type":"strong","children":[{"type":"text","value":"Peak levered IRR"}]},{"type":"text","value":"; the deal's own exit — the hold, or the disposition month when one is set — is marked "},{"type":"strong","children":[{"type":"text","value":"Selected exit"}]},{"type":"text","value":", and the headline figures above the table are that row's figures."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"A row that cannot be a sale shows a dash with its reason, never a zero: "},{"type":"em","children":[{"type":"text","value":"capital still deploying"}]},{"type":"text","value":" (an equity draw or deferred capital lands after that year-end, so a sale before completion is not modelled); the "},{"type":"em","children":[{"type":"text","value":"construction window"}]},{"type":"text","value":" you stated on a development deal has not closed; the "},{"type":"em","children":[{"type":"text","value":"exit NOI is not positive"}]},{"type":"text","value":", so there is no sale value; or the cash flows have one sign and "},{"type":"em","children":[{"type":"text","value":"no IRR"}]},{"type":"text","value":" exists. A development deal that states no construction window and schedules no draws has no construction in the model, and its rows are computed. LP and GP returns are reported at the selected exit only."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Renovation and Year-1 displacement"}]},{"type":"paragraph","attrs":{"testid":"methodology-displacement-explicit-only"},"inline":[{"type":"strong","children":[{"type":"text","value":"Only explicit assumptions displace Year 1."}]},{"type":"text","value":" A renovation budget is a capital cost: it flows into Sources & Uses and the equity requirement, and it never reduces Year-1 occupancy or ADR on its own. Year 1 is displaced only when you set an assumption on CAPEX → Initial Renovation: a Year-1 rooms-offline and rate displacement (each up to half, with a justification note), a renovation displacement schedule, or a structured closure schedule. All default to off, and no document sets them. Years the renovation does not fall in grow from the undisplaced baseline."}]},{"type":"paragraph","attrs":{"testid":"methodology-displacement-schedule"},"inline":[{"type":"strong","children":[{"type":"text","value":"The renovation displacement schedule"}]},{"type":"text","value":" is a list of periods, each with a first and last month counted from close, the share of rooms offline and the rate discount on the rooms that keep selling. Fondok turns it into one occupancy factor and one ADR factor per model year — every month weighs one twelfth, rooms offline across overlapping periods add up, and the rate discount applies only to the rooms that actually sold. Six months at a quarter of rooms offline and ten percent off therefore give Year 1 occupancy times 0.875 and ADR times 0.957. When a schedule is set it is the only renovation impact applied, so nothing is counted twice."}]},{"type":"paragraph","attrs":{"testid":"methodology-displacement-status"},"inline":[{"type":"strong","children":[{"type":"text","value":"The model says what it decided."}]},{"type":"text","value":" The CAPEX tab's renovation row and the Future P&L's Year-1 basis line print the displacement the model actually applied — “No Year-1 renovation impact”, or the percentages it used, or the schedule it ran — so a reader never has to infer it."}]}]},{"type":"container","kind":"card","attrs":{"testid":"methodology-renovation-budget-precedence"},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Renovation budget — which document the model reads"}]},{"type":"container","kind":"chain","attrs":{},"children":[{"type":"list","ordered":true,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Your override"}]},{"type":"text","value":" — A budget you set — including one you selected with \"Use this\" on CAPEX → Renovation budget sources — wins, with its justification note."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"PIP or capital plan — latest plan date"}]},{"type":"text","value":" — A separate PIP, owner budget, approved capital plan or estimate filed in the PIP / Renovation Budget lane that states a total. It is the more detailed source, so it outranks the OM; among several, the newest plan date wins."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"OM broker pro forma"}]},{"type":"text","value":" — The renovation budget the offering memorandum states, when no PIP or capital plan does."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Platform default"}]},{"type":"text","value":" — Used only when no document states a budget, with the reason shown. No budget, whatever its source, displaces Year 1 on its own."}]}]}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Every candidate stays visible. CAPEX → Initial Renovation → "},{"type":"strong","children":[{"type":"text","value":"Renovation budget sources"}]},{"type":"text","value":" lists the OM figure and each PIP or capital-plan figure with its page, plan date, status and preparer, marks the one the model is on, and says why each other one is not. A PIP whose stated total is more than two percent away from the sum of its own scope items is flagged for review; the value is never altered."}]},{"type":"paragraph","attrs":{"testid":"methodology-capex-lanes"},"inline":[{"type":"strong","children":[{"type":"text","value":"Three CapEx lanes, one of which feeds the model."}]},{"type":"text","value":" Every capital document is filed in a lane: "},{"type":"strong","children":[{"type":"text","value":"PIP / Renovation Budget"}]},{"type":"text","value":" is the day-one plan and the only lane the renovation budget reads; "},{"type":"strong","children":[{"type":"text","value":"Historic CapEx"}]},{"type":"text","value":" is spend already incurred; "},{"type":"strong","children":[{"type":"text","value":"Future CapEx"}]},{"type":"text","value":" is a forward capital plan. Historic and Future CapEx are listed as “Reference only — not in the model” and never enter the renovation budget. A capital file dropped without a lane is filed under PIP / Renovation Budget so that is visible; move it to take it out."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Exit cap rate"}]},{"type":"container","kind":"chain","attrs":{},"children":[{"type":"list","ordered":true,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Your override"}]},{"type":"text","value":" — An inline-edited value wins."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"OM comparable sales"}]},{"type":"text","value":" — When the OM carries three or more comparable sales with cap rates in a sensible band, their median is the anchor."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Platform default of 7.0%"}]},{"type":"text","value":" — Used when no comparable sales are extracted, badged as a default."}]}]}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Where expense lines come from"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Departmental, undistributed and fixed-charge lines come from the T-12 first. A zero on the statement is treated as “not stated” rather than a fact, and a line the statement does not carry runs on a ratio: your override first, else your portfolio's ratio when one is on the deal, else the platform default for the hotel type. An uploaded benchmark report changes nothing by itself; its ratio becomes an assumption only when you apply it."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"When a precedence chain ends at a platform default, the default carries the reason — no document of the needed type on the deal, a document that does not state the figure, or market rates that could not be read — in the vocabulary of Section 7. Each grounded value carries the opposite record: the document, page and line behind it."}]}]}]},"sources":{"title":"Where market assumptions come from","blocks":[{"type":"container","kind":"intro","attrs":{},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Every assumption on the Overview carries a source badge saying where the value came from. The legend below explains each badge and the order of precedence between them."}]}]},{"type":"container","kind":"card","attrs":{"testid":"market-tab-methodology"},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"The Market Comps tab: comp set, the trailing-twelve-month blend, demand and supply"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"One comp set, one derivation."}]},{"type":"text","value":" The hotel count and key count on the Market Comps tab come from the same set: the active hotels on the STR roster, combined across every STR report on the deal. A hotel is treated as closed only when a report says so explicitly; closed hotels are listed with a “closed · excluded” chip and are left out of both the count and the keys. Which reports count as STR is decided by the lane each document was processed in, not by its tag, so a market report filed under STR is read as a market study and never feeds the comp set."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"“TTM · comp-set blend” is defined on the card."}]},{"type":"text","value":" Market occupancy, ADR and RevPAR are the comp set's blended trailing-twelve-month figures, recovered exactly from the STR penetration indices: comp-set occupancy is the subject's occupancy divided by its occupancy index, and likewise for ADR and RevPAR. The card prints a methodology line composed from the inputs actually used — the reports, the period and the active hotels. A metric whose index is missing shows a dash rather than a substitute."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Demand growth and supply growth read the market study."}]},{"type":"text","value":" A submarket report feeds both tiles, and every figure names its document and page. Demand growth is the report's own occupied-room-night growth. Under-construction rooms are shown as a share of existing inventory, with the report's own supply-change figure shown alongside and never substituted. A tile the reports cannot populate shows a dash with its reason — no market study on the deal, or a report that does not carry the series. No growth rate is ever assumed."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"container","kind":"badges","attrs":{},"children":[{"type":"container","kind":"badge","attrs":{"source":"t12_actual","name":"T-12 Actual"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Year-1 anchor read from the deal's uploaded T-12. Later years grow forward at the configured revenue and expense growth rates."}]}]},{"type":"container","kind":"badge","attrs":{"source":"cbre_horizons","name":"CBRE Horizons"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Forecast curve read from an uploaded CBRE Hotel Horizons report for the subject's submarket and chain scale."}]}]},{"type":"container","kind":"badge","attrs":{"source":"om_comps","name":"OM Comps"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Median cap rate derived from the OM's comparable-sales table."}]}]},{"type":"container","kind":"badge","attrs":{"source":"om_broker","name":"OM Broker"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"A broker pro forma value read from the OM. Treat with appropriate scepticism — these are the broker's pitched numbers."}]}]},{"type":"container","kind":"badge","attrs":{"source":"pnl_benchmark","name":"P&L Benchmark"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"An industry benchmark ratio from a CBRE or HotStats report. The model no longer applies these on its own; an applied suggestion shows as Analyst Override with its note. The badge can still appear on older runs."}]}]},{"type":"container","kind":"badge","attrs":{"source":"analyst_override","name":"Analyst Override"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Set through an inline editor and carrying your written justification. Wins over every other source — but only a value that actually changed is recorded as one; see “What counts as an override” below."}]}]},{"type":"container","kind":"badge","attrs":{"source":"str_subject_ttm","name":"STR · Subject TTM Actual"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The subject property's own trailing-twelve-month occupancy and ADR as reported by STR — an actual, not a forecast. This is what the Base Year is seeded from when the STR basis is on."}]}]},{"type":"container","kind":"badge","attrs":{"source":"str_comp_set","name":"STR Comp-Set Rates"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The comp set's blended occupancy and ADR shown on the Market Comps tab, applied as the Year-1 input by “Use STR rates in the model”. This is the competitive set's performance, not the subject's own, and the Market Comps tab shows the two as separate figures."}]}]},{"type":"container","kind":"badge","attrs":{"source":"str_forecast","name":"STR Trend Forecast"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The forward-forecast scenario's month-twelve point — a projection of the subject, used only when the subject's own trailing twelve months is not extracted. The P&L shows the active basis and a one-click Revert whenever rates carry any STR tag."}]}]},{"type":"container","kind":"badge","attrs":{"source":"str_forecast_unavailable","name":"STR Unavailable"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"STR rates were requested but could not populate. The model stays on the T-12 base and says so — an STR basis is never silently “active”."}]}]},{"type":"container","kind":"badge","attrs":{"source":"derived_from_revpar_growth","name":"Derived from RevPAR Growth"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"A RevPAR-growth override derives ADR growth with the occupancy path held, so the lever moves operating NOI. Setting ADR growth explicitly takes direct control."}]}]},{"type":"container","kind":"badge","attrs":{"source":"str_segmentation","name":"STR Segmentation"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"A demand-segment figure the deal's STR Segmentation report states: a segment's share of room nights, the transient channel split when the report's channel-mix block carries it, or a segment ADR."}]}]},{"type":"container","kind":"badge","attrs":{"source":"platform_default_segmentation","name":"Platform default — no segmentation data on file"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"A segment-model figure the STR Segmentation report does not state, filled by a platform default: every channel cost (BAR 2%, OTA 20%, corporate 8%, group 5%, contract 2%), the 60/30/10 BAR / OTA / corporate split of transient demand when the report has no channel-mix block, and a segment ADR at its ratio to the property ADR (corporate 90%, group 92%, contract 65%). A suggestion, never labelled as STR data; the Revenue Mix sheet and the memo name these figures under the table. Runs saved before 30 October 2026 carry the older “Segment default” badge on every segment figure."}]}]},{"type":"container","kind":"badge","attrs":{"source":"platform_default_renovation_split","name":"Platform default split"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The renovation budget's breakdown into hard costs, soft costs and professional fees at the platform default 75% / 15% / 10% — no itemized renovation budget is on file."}]}]},{"type":"container","kind":"badge","attrs":{"source":"index_assumption","name":"Index Analysis Assumption"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Index Analysis indexes the subject against one of three benchmarks, chosen on Market Comps → Index Analysis: the "},{"type":"strong","children":[{"type":"text","value":"STR competitive set"}]},{"type":"text","value":" (the default), a "},{"type":"strong","children":[{"type":"text","value":"market or chain-scale benchmark"}]},{"type":"text","value":" from the deal's market reports, or a "},{"type":"strong","children":[{"type":"text","value":"CoStar comp set"}]},{"type":"text","value":" when that export has been extracted. Four assumptions ride on the choice — market occupancy growth, market ADR growth, and the occupancy and rate penetration targets — each showing its document source or “Your override”. They feed the Future P&L only while “Use STR rates in the model” is on; with the toggle off nothing moves. "},{"type":"br"},{"type":"strong","children":[{"type":"text","value":"Targets by year."}]},{"type":"text","value":" Penetration targets can be set per model year; a by-year entry beats the all-years target. The all-years target drives Year 1 only — later years are indexed only where a by-year target is set or you override that metric's market growth; otherwise the year follows the model's own growth and is flagged as applying the all-years target to Year 1 only. A year with a target but no benchmark value is flagged as benchmark unavailable: the model keeps its own growth and no figure is invented. "},{"type":"br"},{"type":"strong","children":[{"type":"text","value":"Target units."}]},{"type":"text","value":" A target is index points from 25 to 250 (100 is parity) or a ratio from 0.25 to 2.5 (1.0 is parity); the two bands do not overlap, so a value names its own unit. A stored target outside both bands is ignored by the model and the panel says so, with a prompt to re-enter it."}]}]},{"type":"container","kind":"badge","attrs":{"source":"index_assumption","name":"Index Analysis · Columns & Rows"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The Index Analysis year columns follow the acquisition close calendar — the same calendar the Future P&L prints. The six columns before Year 1 are history; the forecast columns are exactly the model horizon, and nothing is carried beyond it. Each benchmark value names its kind with a worded chip — "},{"type":"strong","children":[{"type":"text","value":"Actual"}]},{"type":"text","value":" with its period and document, "},{"type":"strong","children":[{"type":"text","value":"Forecast"}]},{"type":"text","value":" with the report and year, or "},{"type":"strong","children":[{"type":"text","value":"Assumption"}]},{"type":"text","value":" for a comp set grown at market growth — never colour alone. STR publishes no comp-set forecast, so comp-set out-years are always an assumption and say so. Penetration rows print a target only when the subject rows actually run on it; otherwise the published index is held flat with a note. Every cell shows its formula and inputs on hover; a cell with no reported input is a dash."}]}]},{"type":"container","kind":"badge","attrs":{"source":"seed","name":"Platform Default"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"A Fondok default used because no deal document has set the value yet, shown in grey. The senior origination fee (1.50% of the senior loan) is one of these: editable on Financing, and the single source for the Sources & Uses origination-fee line and the Overview's Financing Costs."}]}]},{"type":"container","kind":"badge","attrs":{"source":"deal_row","name":"Deal Details"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Entered on the new-deal wizard or the Overview: project name, city, brand, keys, the reopening date — and the "},{"type":"strong","children":[{"type":"text","value":"purchase price"}]},{"type":"text","value":". The wizard's price field is read to whole dollars (“$36.4M”, “36,400,000”; a range stores its midpoint and is labelled as such). Text that does not read as a price is kept as a note and sends nothing — the model keeps its default until you set the price on CAPEX → Deal Summary."}]}]}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"What counts as an override"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Opening a field to inspect it never changes its source. An override is recorded only when the saved value "},{"type":"strong","children":[{"type":"text","value":"differs from the current effective value"}]},{"type":"text","value":" — compared in the field's own unit, so “6.80” typed over a stored 6.8% writes nothing. Every editor exits without writing on Cancel, Escape or a click outside, and a Save that changed nothing says so. The same rule holds for overrides already stored: a value equal to what the deal resolves to on its own is reported under its source's badge, not as an override. Use "},{"type":"strong","children":[{"type":"text","value":"Clear override"}]},{"type":"text","value":" in the source popover to remove one."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Every override carries a justification"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"An override that "},{"type":"strong","children":[{"type":"text","value":"changes a number the model runs on"}]},{"type":"text","value":" carries your written justification, required at the moment of the edit and shown to reviewers beside the number and in the activity trail. The rule is enforced on the server as well as in the editor, so no path — screen, spreadsheet import or integration — can record an unexplained number. The justification is never written for you."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"What is exempt, and why."}]},{"type":"text","value":" Edits that change no modelled number need no note: the Historical P&L's row layout, the Stabilization Year, the Property Name, the completion-guarantee status, the number of promote tiers, and the IC memo's prose. Clearing an override is a return to source and needs no note either."}]},{"type":"paragraph","attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Target levered IRR, target equity multiple and target stabilized yield on cost are not overrides."}]},{"type":"text","value":" They are stated objectives — the benchmark the returns are read against and the hurdle the Max Price Solver prices to — not replacements for a value Fondok read from a document, so they are editable without a justification."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Project Name and Property Name"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Project Name"}]},{"type":"text","value":" is your confidential deal identifier — set and renamed on the Overview; a document never writes it. "},{"type":"strong","children":[{"type":"text","value":"Property Name"}]},{"type":"text","value":" is the asset as named in the offering documents and is never inferred from the Project Name; it shows a dash until the OM is extracted. You may override the Property Name from its Overview row; the extracted value and its source page are kept, and “Restore sourced value” brings them back."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Which documents set the deal's key count, brand and city"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Only documents about the subject property — the Offering Memorandum, a T-12, P&Ls, a hotel program or a property information sheet — can set the key count, and when more than one states a room count the Offering Memorandum wins. The existing brand comes from the OM and fills a blank only; the proposed brand is yours and is never touched by a document. Market reports, STR reports, comparable sets, capital budgets, insurance documents and leases describe other things and never change the key count, brand or city. Until a qualifying document is extracted the deal header shows a dash for keys, never zero."}]},{"type":"paragraph","attrs":{"testid":"brand-positioning-methodology"},"inline":[{"type":"strong","children":[{"type":"text","value":"Brand and positioning."}]},{"type":"text","value":" Positioning is a deal setting, chosen on the wizard's Brand and Positioning step and editable on the Overview. Choosing a brand "},{"type":"em","children":[{"type":"text","value":"suggests"}]},{"type":"text","value":" that brand's STR chain scale wherever STR lists it; a suggestion is only that, and the tier changes only when you select one. When an Offering Memorandum is extracted and the deal has no tier, a confident match on the brand the OM names sets the positioning, and the Overview says where the tier came from — “From OM brand” with the document and page, or “Analyst” for a tier you chose. A tier you chose is never replaced by an OM. The stored tier is what the model reads for the comparable-sales match and for which portfolio ratios may contribute."}]},{"type":"paragraph","attrs":{"testid":"property-type-methodology"},"inline":[{"type":"strong","children":[{"type":"text","value":"Property type."}]},{"type":"text","value":" A deal's property type is one of five: Full-Service, Select-Service, Limited-Service, Extended-Stay or Resort. It is read from the Offering Memorandum only, and only when the OM states it plainly (“boutique lifestyle full-service” reads as Full-Service; “luxury” on its own names a positioning, not a type, and sets nothing). Nothing is assumed when the OM is silent. The comparable-sales match uses the positioning tier; only a deal with no tier falls back to its property type for an approximate scale — Full-Service and Resort as Upper Upscale, Select-Service as Upper Midscale, Limited-Service as Midscale. Extended-Stay spans several scales, so it sets no fallback."}]},{"type":"paragraph","attrs":{"testid":"market-submarket-methodology"},"inline":[{"type":"strong","children":[{"type":"text","value":"City, market and submarket."}]},{"type":"text","value":" These are three separate deal fields. City is the property's city, filled from the OM only while empty. Market and Submarket are chosen on the wizard's first step and correctable on the Overview; no model reads them, so changing them never re-runs the model. When the CoStar market list is available to your workspace, the Market field suggests CoStar's markets — metro markets named by city and state, regional markets named in words — and the Submarket field suggests that market's CoStar submarkets, each shown with its market so two submarkets sharing a name stay distinguishable. A pick is recorded as a CoStar market or submarket; typing a market or submarket that is not suggested is always allowed and is recorded as analyst-entered. Whether the list is available depends on CoStar's licence: until it is confirmed, other workspaces see a public list of STR market names and no submarket suggestions. An Offering Memorandum may fill an empty Market and Submarket only when the city and state it states match exactly one metro market in the list, and its submarket phrase exactly one of that market's submarkets; a regional market is never inferred from a city, two possible matches fill nothing, and a value you entered is never replaced. The Overview says where the market came from. Fondok never invents a market, a submarket or an identifier, and never shows you a vendor identifier."}]},{"type":"paragraph","attrs":{"testid":"market-data-policy-methodology"},"inline":[{"type":"strong","children":[{"type":"text","value":"Market defaults may be withheld for a workspace."}]},{"type":"text","value":" A market default derived from a licensed vendor's report (a CoStar submarket forecast, for instance) may be withheld for a workspace until that licensing is confirmed for it; a withheld default is shown as not applied with its reason, never replaced by a number, and the workspace's own uploaded figures are unaffected."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Which statement is the Year-1 basis"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Year-1 occupancy, ADR, revenue lines and expense lines all come from one statement: the document the Data Room badges as "},{"type":"strong","children":[{"type":"text","value":"Primary source"}]},{"type":"text","value":". The model and the badge share one ranking — full-year statements before partial ones, the most recent period first, a T-12 ahead of a calendar-year P&L of the same year. Older annual P&Ls never blend into Year 1: a line is corroborated only across statements that describe the same period, so every Year-1 number traces to a single row of the primary statement. Earlier years still feed the Historical P&L and the variance checks."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Hover any number to trace it"}]},{"type":"list","ordered":false,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Inputs — “where did this come from?”"}]},{"type":"text","value":" Assumptions show a source badge coloured by origin: green when grounded in the deal's own documents, amber when still a default or benchmark, violet when you overrode it. A badge backed by a document is clickable and jumps to that source in the Data Room."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Outputs — “how was this computed?”"}]},{"type":"text","value":" Modelled values — revenue, NOI, debt service, DSCR, equity multiple, sale price, IRR — show their formula and every named input on hover, and each input chains one hop further, back to a document, a default, an override or another computed value."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"NOI pin."}]},{"type":"text","value":" A deal can carry an analyst-entered NOI schedule used to reconcile to a source model. While it is set, the Debt and Returns models read that schedule instead of the operating model, so operating edits do not move NOI; the Future P&L shows an “NOI pinned” notice with a one-click clear, after which NOI follows the operating assumptions again."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"IRR is calculated, and says so."}]},{"type":"text","value":" IRR is the discount rate that sets the equity cash flows to zero, solved iteratively. Its hover says so and lists the year-by-year cash flows the solver ran over."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Total Revenue is the statement's own line."}]},{"type":"text","value":" On the Historical P&L the Total Revenue row shows the statement's stated total when it publishes one, and the sum of the extracted lines — labelled calculated — only when it does not. The Revenue footing row under the grid always compares the two and shows the difference; no total is invented when neither exists."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Every historical column states its period."}]},{"type":"text","value":" A statement is read as a full year, a year to date through a month end, or a trailing twelve months ending at a month end, and the column header says which. When the basis cannot be established the column shows the bare year with a “basis unknown” chip, never an invented period."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Cross-checked across statements."}]},{"type":"text","value":" When more than one full-year statement covers the same period, each revenue and expense line is cross-checked and Year 1 is grounded on the corroborated value, so one misread line cannot skew the model. A line reported by only one statement is used as-is."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"One review state, Data Room and P&L."}]},{"type":"text","value":" A value is “to review” when its extraction confidence is below the threshold and it has not been accepted or corrected. The Data Room's per-statement count is exactly the number of flagged cells in that statement's column; accepting or correcting a value clears both at once."}]}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"As-of rule"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"An underwriting is a claim about what was knowable on a date. When a deal sets an underwriting as-of date, Fondok will not ground a market assumption on a report published after it: the assumption keeps the basis it already had and the badge says unavailable with the reason, never a silent substitution. A report whose date cannot be established is used and flagged — a missing date is a caveat, not grounds to withhold a number. The same date anchors the comparable-sales lookback, so re-opening a deal months later does not quietly age its comp set out of the window."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"The full ledger"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The Sources ledger, linked from every traced figure's tooltip, lists every modelled assumption, its value and its origin in one table. Filter to the ungrounded set to see exactly what is still riding on a default, and export the ledger so every figure in the IC memo is defensible."}]}]}]},"engines":{"title":"How the model is organised","blocks":[{"type":"container","kind":"intro","attrs":{},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Eight deterministic models run in dependency order and publish their results together, so every tab reads one consistent snapshot."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"container","kind":"deflist","attrs":{},"children":[{"type":"list","ordered":false,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Revenue"}]},{"type":"text","value":" Rooms × occupancy × ADR, plus F&B, other operated departments, resort fees and miscellaneous income."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"F&B"}]},{"type":"text","value":" A per-occupied-room F&B model with a food and beverage split; resort fees are a separate line."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Expense"}]},{"type":"text","value":" USALI departmental and undistributed lines, management fee, FF&E reserve and fixed charges, to gross operating profit, NOI and net cash flow."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Capital"}]},{"type":"text","value":" Purchase price, closing costs, renovation budget and working capital, plus the senior origination fee owned by the Financing tab — the Sources & Uses."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Debt"}]},{"type":"text","value":" The senior and PACE tranches from your entered terms — fixed or floating, amortising or interest-only, maturity — with the monthly schedule, DSCR, debt yield, LTV and LTC, covenants and refinancing."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Returns"}]},{"type":"text","value":" Levered and unlevered IRR, equity multiple, cash-on-cash, the sale value from the exit cap rate and exit NOI, and the returns schedule by exit year. A loss-making deal is reported honestly — a negative IRR or a multiple below one is never floored."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Sensitivity"}]},{"type":"text","value":" IRR and equity multiple across exit cap, hold, growth and other pairs."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Partnership"}]},{"type":"text","value":" The GP / LP waterfall with preferred return, catch-up and promote tiers. It runs only on the deal's own partnership terms; without them it reports “not applicable — no partnership terms on this deal”. A shortfall is funded as a dated pro-rata capital call that adds to unreturned capital, and is reported as additional contributions."}]}]}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Financing is an assumptions workspace"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Debt documents are optional. The Financing tab is where the financing is entered, and every core term is your input — Fondok does not read a term sheet in this release. Each edit is saved as an override "},{"type":"badge","source":"analyst_override"},{"type":"text","value":" and re-runs the chain, so the schedule, DSCR, debt yield, Cash Flow and Returns reflect what was entered. A year whose NOI is negative does not stop the model: its DSCR shows as not applicable, the uncovered debt service is reported as that year's shortfall, and the tab names the negative years in one warning."}]},{"type":"list","ordered":false,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Senior loan."}]},{"type":"text","value":" Amount or LTV (either resizes the same loan), rate basis, amortisation, an interest-only period, and maturity. A floating rate prices off the index assumption plus spread, clamped to an optional floor and cap; until an index is entered the build-up shows Fondok's flat index assumption and says it is not market data."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"PACE loan."}]},{"type":"text","value":" Funding an amount adds it to total debt, LTV, LTC and debt yield immediately. Until a rate is entered the tranche is "},{"type":"em","children":[{"type":"text","value":"terms pending"}]},{"type":"text","value":": it stays out of debt service and DSCR rather than running on an invented rate."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Covenants."}]},{"type":"text","value":" Maximum LTV and LTC and minimum DSCR and debt yield are thresholds you enter. There is no default package — a covenant without a threshold shows its live reading, an input, and no pass or fail verdict."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Senior origination fee."}]},{"type":"text","value":" A platform default of 1.50% of the senior loan "},{"type":"badge","source":"seed"},{"type":"text","value":" until you change it. Financing is its only owner: Sources & Uses, total uses, required equity and LTC all move with it, and at zero the line disappears."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Missing inputs are inputs."}]},{"type":"text","value":" Wherever a required assumption is absent, the tab renders the input to provide — “Enter rate”, “Enter spread”, “Enter threshold” — with the consequence stated, instead of an unexplained dash."}]}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"The Returns sandbox"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Overview → Returns → Sensitivities carries a "},{"type":"strong","children":[{"type":"text","value":"Live Assumptions"}]},{"type":"text","value":" card whose sliders are a sandbox, not an edit. It answers “what would this deal do if…” without changing what the deal "},{"type":"em","children":[{"type":"text","value":"is"}]},{"type":"text","value":"."}]},{"type":"list","ordered":false,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Five assumptions, and only five."}]},{"type":"text","value":" Exit cap rate, RevPAR growth, hold period, LTV and interest rate. Nothing else can be reached from the sandbox."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"The sliders start where the run started."}]},{"type":"text","value":" Each slider's base is the value the saved run recorded, never a default typed into the screen. A run that did not record one of the five shows “Awaiting model run” in place of the sliders."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"It runs the whole chain, in memory."}]},{"type":"text","value":" Nothing is written: no run, no change to the deal's assumptions. CAPEX and Financing keep showing the Base Case throughout. While the sandbox differs from the Base Case a banner spans the Returns section and every tile that moved carries a Sandbox chip."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"It survives navigation, and only that."}]},{"type":"text","value":" Held in your browser session, per deal. Reset to base case, opening a different deal or a fresh model run clears it. It is never shared, bookmarked or seen by anyone else, and the Max Price Solver and the pricing grid do not consume it."}]}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"When a model cannot finish"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The models are independent, so one can fail without taking down the rest. When one does, the deal shows a red banner naming the model, a plain-language reason and a one-click Re-run; the numbers it feeds read as an explicit error, never as silent dashes that look like missing data. When a deal's saved run is older than the current version of Fondok, an amber banner says so and names the tabs affected, with the same Re-run."}]}]}]},"pricing":{"title":"Return targets and the Max Price Solver","blocks":[{"type":"container","kind":"intro","attrs":{},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"The hurdles a deal must clear are yours, set once on Overview → Investment Profile. Pricing reads them from the deal — there is no hidden default hurdle anywhere in the pricing path."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"The Investment Profile is the source of truth"}]},{"type":"list","ordered":false,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Two pricing hurdles."}]},{"type":"text","value":" "},{"type":"strong","children":[{"type":"text","value":"Target levered IRR"}]},{"type":"text","value":" and "},{"type":"strong","children":[{"type":"text","value":"target equity multiple"}]},{"type":"text","value":" are stored on the deal as your inputs "},{"type":"badge","source":"analyst_override"},{"type":"text","value":". Either may be unset; an unset target renders as a dash."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"The return profile is a preset."}]},{"type":"text","value":" The target levered IRR control carries a preset for each return profile — Core 5–10%, Core Plus 7–12%, Value Add 11–17%, Opportunistic 18%+. Choosing one writes the band's midpoint as the target (an open band writes its floor) — an explicit action, never applied implicitly. You can then edit the number."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Benchmark only."}]},{"type":"text","value":" Saving a target never re-runs the model. The Overview compares the calculated levered IRR against the target: below it is "},{"type":"em","children":[{"type":"text","value":"Below target"}]},{"type":"text","value":", at or up to two points over is "},{"type":"em","children":[{"type":"text","value":"Within target"}]},{"type":"text","value":", and more than two points over is "},{"type":"em","children":[{"type":"text","value":"Above target"}]},{"type":"text","value":". Display only."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Target stabilized yield on cost."}]},{"type":"text","value":" Compared against the stabilized year's NOI divided by total capital, both from the model run — Pass at or above the target, Short below it. With no stabilized year or no total capital the actual is a dash, never estimated."}]}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Max Price Solver (Overview → Returns → Pricing)"}]},{"type":"list","ordered":false,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"No silent hurdles."}]},{"type":"text","value":" If the deal carries no target, the Pricing block says so with a link to the Investment Profile and shows no numbers."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Lower-of rule."}]},{"type":"text","value":" Each hurdle is solved independently by searching on purchase price with the loan amount held fixed and equity flexing, between half and twice the current basis. Max Price is the lower of the two solved prices, and the binding constraint is named. With one target set, that hurdle governs alone."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Unreachable hurdles stay unreachable."}]},{"type":"text","value":" A hurdle no price down to half the basis can clear reports “no price clears the hurdles”; one that clears even at twice the basis reports that instead. The search boundary is never shown as a price."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Pricing sensitivity grid."}]},{"type":"text","value":" The solver re-runs per cell over exit cap rate and RevPAR growth around the base assumptions. Each cell shows the maximum purchase price clearing both hurdles with its binding constraint, and the base cell reproduces the headline solve exactly."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Exports price to your targets, or say they cannot."}]},{"type":"text","value":" The Excel model's Pricing Sensitivity sheet and the IC memo's Max-Price Findings solve against the same Investment Profile targets as the on-screen solver. With no target on the deal, the sheet and the memo section read “Pricing to target not available: no return target set on this deal” and carry no solver output; with only a target equity multiple, the max price solves that hurdle alone and the IRR grid is omitted (its breakeven sweep needs an IRR target). The LOI draft prices at the solver's offerable headline and refuses — with the reason — when the deal record has no property name or key count, or when no price clears the hurdle."}]}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"What the exports never do"}]},{"type":"list","ordered":false,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Invent a number."}]},{"type":"text","value":" A figure the deal does not carry prints as “not available: <reason>” naming the field (headline cells, assumption rows, section notes) or as a dash inside a table whose header names the field — never 0, 0% or $0. Totals are stated only when every component is; a missing component is named instead. The Debt Schedule sheet is the debt engine's own monthly schedule, never re-derived from headline terms."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Synthesize a sensitivity grid."}]},{"type":"text","value":" The IC deck's heat-map is the Sensitivity engine's persisted output for the deal's canonical run. If that engine has not run, failed, or produced no cells, the slide states “Sensitivity analysis not available: <reason>”. The deck carries no generic “next steps”."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Hide a default."}]},{"type":"text","value":" The Op-Ratio Provenance sheet and memo section are always produced for a modelled deal; when every ratio is a hotel-type seed they say so (“all operating ratios are hotel-type defaults; no T-12 was provided”). Wherever an exported debt figure rides on Fondok's flat SOFR assumption, the export prints the same note the Financing tab shows. The unsourced brand recovery multiplier table is no longer printed."}]}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Asking versus bidding price (Overview KPIs)"}]},{"type":"list","ordered":false,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Two comparable sets."}]},{"type":"text","value":" On an acquisition the Overview shows the same metrics twice — purchase price, total capitalisation, renovation, stabilized NOI, levered and unlevered IRR — once at the "},{"type":"em","children":[{"type":"text","value":"asking"}]},{"type":"text","value":" price and once at the "},{"type":"em","children":[{"type":"text","value":"bidding"}]},{"type":"text","value":" price. Nothing is saved."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Asking price."}]},{"type":"text","value":" The OM's asking price as extracted. With no OM price the modelled purchase price stands in and is labelled with its source."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Bidding price — solved backward from the target."}]},{"type":"text","value":" The Max Price Solver run on the IRR hurdle alone: the purchase price at which the levered IRR equals your target, with the loan held and equity absorbing the difference. With no target the bidding set reads “Set target levered IRR to solve” and shows no numbers."}]}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Investment Bridge"}]},{"type":"list","ordered":false,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Equity invested to equity returned."}]},{"type":"text","value":" A waterfall from the equity funded at close to the total cash returned to equity, deal-level before the GP / LP split, read from the Base Case run."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Five legs."}]},{"type":"text","value":" "},{"type":"em","children":[{"type":"text","value":"Acquisition"}]},{"type":"text","value":" is every use except renovation and the loan fee; "},{"type":"em","children":[{"type":"text","value":"Renovation"}]},{"type":"text","value":" is the renovation line including contingency; "},{"type":"em","children":[{"type":"text","value":"Operations"}]},{"type":"text","value":" is NOI over the hold; "},{"type":"em","children":[{"type":"text","value":"Financing"}]},{"type":"text","value":" is loan proceeds less the origination fee, debt service and the payoff at exit, plus any refinancing proceeds; "},{"type":"em","children":[{"type":"text","value":"Exit"}]},{"type":"text","value":" is the sale price less selling costs and transfer tax."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"It foots by construction."}]},{"type":"text","value":" Equity invested plus the five legs equals equity returned exactly, and the tab states the check. A leg the run cannot support shows a dash with the reason, never a zero bar, and the bridge then says it does not foot."}]}]}]}]},"ic-memo":{"title":"IC Memo — diligence flags and the decision","blocks":[{"type":"container","kind":"intro","attrs":{},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"How broker-versus-actual variance flags reach the committee, what an NOI impact on a flag means, how diligence status is kept, and why the recommendation is a recorded decision rather than a model inference."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"list","ordered":false,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"One flag per business concept."}]},{"type":"text","value":" The variance report groups the broker's claims by concept — rooms revenue, F&B revenue, total revenue, occupancy, ADR, RevPAR, gross operating profit, NOI and each expense line — and the memo lists one item per concept with a readable title (“Rooms revenue — broker overstates T-12 by 5.3%”). The underlying rows stay available under Technical detail on each item and in the exported variance sheet."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"“Estimated NOI impact” only when the delta is an NOI delta."}]},{"type":"text","value":" A dollar NOI impact is shown only for the NOI and gross-operating-profit concepts. A revenue, KPI or expense variance says that its NOI impact is not estimated rather than showing a dollar figure — Fondok does not translate a revenue delta into NOI without a flow-through assumption."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Diligence status is kept per concept."}]},{"type":"text","value":" Resolve, Accept variance and Reopen are recorded on the deal, so the IC-readiness checklist and the Excel export read the same status after a reload. Fondok never resolves a flag on its own."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"The recommendation is a decision, not an inference."}]},{"type":"text","value":" The Model Assessment card shows the model's own read of the Base Case — Clears Hurdles, Clears with Conditions or Below Hurdles — labelled as the model's. The IC recommendation reads "},{"type":"em","children":[{"type":"text","value":"Pending analyst decision"}]},{"type":"text","value":" until you select Proceed, Proceed with Conditions or Do Not Proceed "},{"type":"em","children":[{"type":"text","value":"and"}]},{"type":"text","value":" confirm it. Only the confirmed verdict is written into the memo and the export header."}]}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"What a variance flag compares — and what it refuses to"}]},{"type":"list","ordered":false,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Only the broker's own claim is the broker side."}]},{"type":"text","value":" A figure from a T-12 or P&L is an actual, never a broker figure; a reading from an STR or market report is reported performance, not the broker's claim; a competitive-set statistic or the OM's historical block is neither. Rows excluded for one of these reasons are still listed under Technical detail with the reason."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Units are normalised before comparing."}]},{"type":"text","value":" Ratios are compared as fractions and currency in whole dollars. A value whose unit cannot be established is not compared, and a percentage claim is never read against a dollar line — Fondok does not reconstruct dollars from a percent whose denominator is itself an unverified broker figure."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Annual against annual."}]},{"type":"text","value":" The actual side is the document's annual or trailing-twelve-month line, never a monthly or quarterly slice, and the T-12 is preferred over a supporting P&L. Fondok never compares a month against a year."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Plausibility guard."}]},{"type":"text","value":" A pair of figures more than three hundred percent apart is reported as “Basis mismatch — needs review” with both figures and no severity: two numbers that far apart are on different bases, not evidence of an overstatement."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"NOI is compared like for like across the FF&E reserve."}]},{"type":"text","value":" A broker pro forma states NOI before the reserve while the normalised actual is after it. When the statement states its own before-reserve line, the broker's claim is compared against that one and the row says so; when it does not, the pair is refused as a basis mismatch. The before-reserve figure is only ever read from the document, never reconstructed."}]}]}]}]},"reasons":{"title":"What a dash means","blocks":[{"type":"container","kind":"intro","attrs":{},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Where Fondok cannot produce a figure it shows a dash — never a placeholder, a zero, or a number carried over from a prototype. A deal with no key count or purchase price does not run at all: the model never substitutes a placeholder property, and the run names the missing inputs. Every such refusal has one of the reasons below, and hovering the dash shows it."}]}]},{"type":"container","kind":"card","attrs":{"flush":"true"},"children":[{"type":"slot","name":"reason-code-table"}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"How to read a dash"}]},{"type":"list","ordered":false,"attrs":{},"items":[{"attrs":{"testid":"dash-rule"},"inline":[{"type":"strong","children":[{"type":"text","value":"A figure with no source renders as —."}]},{"type":"text","value":" That holds for every number on every screen and in every export: a room count the documents have not stated yet, a confidence score before any field has been read, a projection line the model did not produce, a return the engine did not compute. Nothing is filled in with a zero, an estimate or a sample figure, and the exported workbook leaves the same cell empty."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"One glyph, many reasons."}]},{"type":"text","value":" Every reason renders the same dash; the hover text is what distinguishes them."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Where it lands on the Data Key."}]},{"type":"text","value":" “Needs review”, “Basis mismatch”, “Period mismatch” and “Unit unknown” describe a figure that exists but cannot be trusted or compared, so they read as "},{"type":"em","children":[{"type":"text","value":"Needs review"}]},{"type":"text","value":". Every other reason means the figure is not there yet and reads as "},{"type":"em","children":[{"type":"text","value":"Awaiting data"}]},{"type":"text","value":"."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"A dash is not an error."}]},{"type":"text","value":" A model that could not finish shows the red banner described in Section 4, naming the model and the reason it stopped, with a Re-run. A screen whose results could not be fetched at all says so, with a Retry, rather than pretending the model has not run. A dash is the model declining to invent a number it has no grounds for — the reason says which grounds are missing."}]}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Structure edits change how a statement reads, never what it computes"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"On the Historical P&L, "},{"type":"strong","children":[{"type":"text","value":"Customize structure"}]},{"type":"text","value":" lets you relabel a line, split one line into parts that must reconcile to the locked parent, reorder lines within their section, hide a line, and add a line of your own. All five are presentation: the value behind each row, the document it was read from and its Data Key state are untouched, and no model reads an added line. The layout is stored on the deal, so every reviewer reads the statement as you arranged it, and "},{"type":"strong","children":[{"type":"text","value":"Reset layout"}]},{"type":"text","value":" restores the canonical statement."}]}]}]},"lineage":{"title":"Every number traces back","blocks":[{"type":"container","kind":"intro","attrs":{},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Pick any headline number on a deal and Fondok can show the chain that produced it, one step at a time, down to the page of the document it was read from — or state, in the vocabulary of Section 7, exactly why the chain stops short."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"The walk"}]},{"type":"container","kind":"chain","attrs":{},"children":[{"type":"list","ordered":true,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Headline number"}]},{"type":"text","value":" — levered IRR, unlevered IRR, equity multiple, Year-1 cash-on-cash, minimum DSCR, Year-1 NOI. These are the roots you can start from."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Modelled value"}]},{"type":"text","value":" — the value behind it, and each value behind that — IRR to the cash flows, cash flows to NOI and debt service, NOI to gross operating profit, profit to revenue, revenue to rooms revenue."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Assumption"}]},{"type":"text","value":" — the underwriting input the calculation rests on — starting occupancy, starting ADR, exit cap rate, LTV — carrying the source that produced it."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Extracted field"}]},{"type":"text","value":" — the exact field on the exact extraction that supplied the assumption, with the concept it resolved to and the basis and period it carries."}]},{"attrs":{},"inline":[{"type":"strong","children":[{"type":"text","value":"Document and page"}]},{"type":"text","value":" — the uploaded document, and the page the number sits on. This is where a walk that closes ends."}]}]}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Three chains end deliberately short of a page, and each says so. Your "},{"type":"strong","children":[{"type":"text","value":"override"}]},{"type":"text","value":" ends at the override, carrying your justification. A "},{"type":"strong","children":[{"type":"text","value":"platform default"}]},{"type":"text","value":" ends at the default. A "},{"type":"strong","children":[{"type":"text","value":"benchmark"}]},{"type":"text","value":" — a market forecast, an industry data set, your own portfolio, an STR feed — ends at the benchmark, and continues to a page only when the benchmark itself arrived as an uploaded document. Each link also says whether the model asserted it or Fondok inferred it from the dependency between models."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"What “stale” means"}]},{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"A chain describes one model run, so it is only as current as that run's inputs. When a document is uploaded, the deal record edited, or a document the run relied on deleted "},{"type":"em","children":[{"type":"text","value":"after"}]},{"type":"text","value":" the run started, the chain is marked stale. Stale does not mean wrong and it does not hide the chain: the evidence shown is still exactly what produced the numbers on screen. It means the deal has moved since, and re-running the model will produce a different chain."}]}]}]},"regression-baselines":{"title":"Telling an intended change from a calculation drift","blocks":[{"type":"container","kind":"intro","attrs":{},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Every model run is kept, so the numbers a deal showed before a change can always be put next to the numbers it shows after — field by field, with the source of each side."}]}]},{"type":"container","kind":"card","attrs":{"testid":"methodology-regression-baselines"},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"Each run is kept and never overwrites an earlier one. The "},{"type":"strong","children":[{"type":"text","value":"Compare runs"}]},{"type":"text","value":" panel at the top of a deal's Activity tab picks a baseline — by default the newest complete run before a date you choose — and a head run, by default the run every tab is showing now. It lists each headline output that moved, grouped by model: occupancy, ADR, RevPAR, revenue, expense lines, management fee, FF&E reserve, gross operating profit and both NOI figures for each year; purchase price, total capitalisation, equity and renovation; loan amount and DSCR by year; levered and unlevered IRR, equity multiple, exit value and exit NOI; the selected exit month, the peak levered exit year and each exit-year row's IRRs, equity multiple and net proceeds; the stabilization block; and LP and GP IRR. Each row shows both values, the absolute change and the percentage change, with each side's source. The same table exports to Excel. Comparing never re-runs or edits the model."}]}]}]},"controls":{"title":"What is yours to set, and what the model derives","blocks":[{"type":"container","kind":"intro","attrs":{},"children":[{"type":"paragraph","attrs":{},"inline":[{"type":"text","value":"A short summary of the division of labour."}]}]},{"type":"container","kind":"card","attrs":{},"children":[{"type":"container","kind":"columns","attrs":{},"children":[{"type":"container","kind":"column","attrs":{"icon":"Pencil"},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Analyst-controlled"}]},{"type":"list","ordered":false,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"text","value":"Deal details: name, market, submarket, keys, brands, operating model, positioning, dates."}]},{"attrs":{},"inline":[{"type":"text","value":"Purchase price and the acquisition close date."}]},{"attrs":{},"inline":[{"type":"text","value":"Every financing term, covenant threshold and refinancing assumption."}]},{"attrs":{},"inline":[{"type":"text","value":"Return targets and the return profile."}]},{"attrs":{},"inline":[{"type":"text","value":"Renovation displacement, the stabilization year, the hold period and the exit NOI basis."}]},{"attrs":{},"inline":[{"type":"text","value":"Any assumption override, each with a justification note."}]},{"attrs":{},"inline":[{"type":"text","value":"The IC recommendation and the diligence status of each flag."}]}]}]},{"type":"container","kind":"column","attrs":{"icon":"BarChart3"},"children":[{"type":"heading","level":4,"inline":[{"type":"text","value":"Model-derived"}]},{"type":"list","ordered":false,"attrs":{},"items":[{"attrs":{},"inline":[{"type":"text","value":"Every extracted figure, with its page and confidence."}]},{"attrs":{},"inline":[{"type":"text","value":"Year-1 anchors from the primary statement and the growth of later years."}]},{"attrs":{},"inline":[{"type":"text","value":"Sources & Uses, the debt schedule, coverage ratios and the cash flow statement."}]},{"attrs":{},"inline":[{"type":"text","value":"Returns, the sale value, the sensitivity grids and the partnership waterfall."}]},{"attrs":{},"inline":[{"type":"text","value":"Variance flags and the model's own assessment of the Base Case."}]},{"attrs":{},"inline":[{"type":"text","value":"The source and lineage of every number on screen."}]}]}]}]},{"type":"paragraph","attrs":{"testid":"methodology-hold-defaults"},"inline":[{"type":"strong","children":[{"type":"text","value":"Hold period defaults."}]},{"type":"text","value":" Until you set the hold, the model applies a labelled default by deal type: 5 years for an acquisition, 7 years for a ground-up development and 6 years for an adaptive reuse. A development or adaptive-reuse hold is badged “Default for development deals — confirm” wherever it is printed, with the reason, so a default is never mistaken for a figure from the deal. Your hold period override replaces it."}]}]}]}};
